SELECT MATRIZ, NOME_MATRIZ, CODPARC, RAZAOSOCIAL, CODEMP, NOMEFANTASIA, CODVEND, APELIDO, CODTIPOPER, DESCROPER, CODTIPVENDA, VLRNOTA, NUNOTA, NUMNOTA, DTFATUR, CODPROJ, IDENTIFICACAO, TIPMOV FROM Vendas WHERE 1=1 AND (DTFATUR >= CASE WHEN :VAR_DT_INICIO IS NULL OR LTRIM(RTRIM(:VAR_DT_INICIO)) = '' OR ISDATE(:VAR_DT_INICIO) = 0 THEN DATEFROMPARTS(YEAR(GETDATE()), 1, 1) ELSE CONVERT(date, :VAR_DT_INICIO, 23) END AND DTFATUR < DATEADD(DAY, 1, CASE WHEN :VAR_DT_FIM IS NULL OR LTRIM(RTRIM(:VAR_DT_FIM)) = '' OR ISDATE(:VAR_DT_FIM) = 0 THEN CAST(GETDATE() AS date) ELSE CONVERT(date, :VAR_DT_FIM, 23) END)) AND (:VAR_PARCEIRO IS NULL OR LTRIM(RTRIM(:VAR_PARCEIRO)) = '' OR CHARINDEX(',' + CONVERT(varchar(50), CODPARC) + ',', ',' + REPLACE(LTRIM(RTRIM(:VAR_PARCEIRO)),' ','') + ',') > 0) AND (:VAR_EMPRESA IS NULL OR LTRIM(RTRIM(:VAR_EMPRESA)) = '' OR CHARINDEX(',' + CONVERT(varchar(50), CODEMP) + ',', ',' + REPLACE(LTRIM(RTRIM(:VAR_EMPRESA)),' ','') + ',') > 0) AND (:VAR_PROJETO IS NULL OR LTRIM(RTRIM(:VAR_PROJETO)) = '' OR CHARINDEX(',' + CONVERT(varchar(50), CODPROJ) + ',', ',' + REPLACE(LTRIM(RTRIM(:VAR_PROJETO)),' ','') + ',') > 0) AND (:VAR_TIPO_OPERACAO IS NULL OR LTRIM(RTRIM(:VAR_TIPO_OPERACAO)) = '' OR CHARINDEX(',' + CONVERT(varchar(50), CODTIPOPER) + ',', ',' + REPLACE(LTRIM(RTRIM(:VAR_TIPO_OPERACAO)),' ','') + ',') > 0) AND (:VAR_NUMNOTA IS NULL OR LTRIM(RTRIM(:VAR_NUMNOTA)) = '' OR NUMNOTA = CONVERT(int, :VAR_NUMNOTA)) AND (:VAR_NUNOTA IS NULL OR LTRIM(RTRIM(:VAR_NUNOTA)) = '' OR NUNOTA = CONVERT(int, :VAR_NUNOTA)) AND (:VAR_VLR_MIN IS NULL OR LTRIM(RTRIM(:VAR_VLR_MIN)) = '' OR VLRNOTA >= CONVERT(numeric(18,2), :VAR_VLR_MIN)) AND (:VAR_VLR_MAX IS NULL OR LTRIM(RTRIM(:VAR_VLR_MAX)) = '' OR VLRNOTA <= CONVERT(numeric(18,2), :VAR_VLR_MAX)) AND (:VAR_MATRIZ IS NULL OR LTRIM(RTRIM(:VAR_MATRIZ)) = '' OR CHARINDEX(',' + CONVERT(varchar(50), MATRIZ) + ',', ',' + REPLACE(LTRIM(RTRIM(:VAR_MATRIZ)),' ','') + ',') > 0) ORDER BY NOME_MATRIZ ASC, DTFATUR DESC